# Shared helpers for the Java audit fact sheets: comment/string stripping and brace matching.
# Regex-based on purpose (no parser dependency); every heuristic yields candidates, never verdicts.
import os
import re


def strip_java(src):
    """Blank out comments, string/char literals and text blocks, keeping offsets and newlines."""
    out = list(src)
    i, n = 0, len(src)

    def blank(a, b):
        for k in range(a, b):
            if out[k] != '\n':
                out[k] = ' '

    while i < n:
        c = src[i]
        if src.startswith('//', i):
            j = src.find('\n', i)
            j = n if j < 0 else j
            blank(i, j)
            i = j
        elif src.startswith('/*', i):
            j = src.find('*/', i + 2)
            j = n if j < 0 else j + 2
            blank(i, j)
            i = j
        elif src.startswith('"""', i):
            j = src.find('"""', i + 3)
            j = n if j < 0 else j + 3
            blank(i + 1, j - 1)
            i = j
        elif c == '"' or c == "'":
            j = i + 1
            while j < n and src[j] != c and src[j] != '\n':
                j += 2 if src[j] == '\\' else 1
            j = min(j + 1, n)
            blank(i + 1, j - 1)
            i = j
        else:
            i += 1
    return ''.join(out)


def match_brace(s, open_idx):
    """Index of the brace closing the one at open_idx, or len(s)."""
    depth = 0
    for k in range(open_idx, len(s)):
        ch = s[k]
        if ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth == 0:
                return k
    return len(s)


def match_paren(s, open_idx):
    depth = 0
    for k in range(open_idx, len(s)):
        ch = s[k]
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth == 0:
                return k
    return len(s)


def line_of(s, idx):
    return s.count('\n', 0, idx) + 1


MODIFIERS = r'(?:(?:public|protected|private|static|final|synchronized|abstract|native|default|strictfp)\s+)*'
METHOD_RE = re.compile(
    r'(?P<annos>(?:@\w+(?:\.\w+)*(?:\([^()]*(?:\([^()]*\)[^()]*)*\))?\s+)*)'
    r'(?P<mods>' + MODIFIERS + r')'
    r'(?:<[^<>]*(?:<[^<>]*>[^<>]*)*>\s+)?'
    r'(?P<ret>[\w.$]+(?:<[^;{}()]*?>)?(?:\[\])*)\s+'
    r'(?P<name>[a-zA-Z_$][\w$]*)\s*\((?P<params>[^;{}()]*(?:\([^()]*\)[^;{}()]*)*)\)\s*'
    r'(?:throws\s+[\w.$,\s]+)?\{')
CTOR_KEYWORDS = {'if', 'for', 'while', 'switch', 'catch', 'synchronized', 'return', 'new', 'else', 'try', 'do'}


def methods(stripped):
    """Method declarations with body span: dicts name/mods/annos/params/start/end/line."""
    found = []
    for m in METHOD_RE.finditer(stripped):
        name = m.group('name')
        if name in CTOR_KEYWORDS or m.group('ret') in CTOR_KEYWORDS:
            continue
        body_open = m.end() - 1
        found.append({
            'name': name,
            'mods': m.group('mods').split(),
            'annos': m.group('annos'),
            'params': m.group('params').strip(),
            'ret': m.group('ret'),
            'start': body_open,
            'end': match_brace(stripped, body_open),
            'line': line_of(stripped, m.start('name')),
        })
    return found


def java_files(root):
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = sorted(d for d in dirnames if d not in ('build', 'node_modules') and not d.startswith(('.', 'target')))
        for f in sorted(filenames):
            if f.endswith('.java'):
                yield os.path.join(dirpath, f)


def java_version(base):
    """(version, source) from Maven or Gradle build files, or (None, reason)."""
    pats = [
        (r'<maven\.compiler\.release>\s*(\d+)', 'maven.compiler.release'),
        (r'<java\.version>\s*(\d+)', 'java.version'),
        (r'<release>\s*(\d+)\s*</release>', 'compiler release'),
        (r'<maven\.compiler\.source>\s*(?:1\.)?(\d+)', 'maven.compiler.source'),
        (r'JavaLanguageVersion\.of\(\s*(\d+)', 'gradle toolchain'),
        (r'sourceCompatibility\s*=\s*[\'"]?(?:JavaVersion\.VERSION_)?(?:1[._])?(\d+)', 'gradle sourceCompatibility'),
    ]
    for dirpath, dirnames, filenames in os.walk(base):
        dirnames[:] = [d for d in dirnames if d not in ('build', 'node_modules') and not d.startswith(('.', 'target'))]
        if dirpath.count(os.sep) - base.count(os.sep) > 2:
            dirnames[:] = []
        for f in ('pom.xml', 'build.gradle', 'build.gradle.kts'):
            if f in filenames:
                try:
                    text = open(os.path.join(dirpath, f), encoding='utf-8', errors='replace').read()
                except OSError:
                    continue
                for pat, label in pats:
                    m = re.search(pat, text)
                    if m:
                        return int(m.group(1)), os.path.relpath(os.path.join(dirpath, f), base) + ' ' + label
    return None, 'no pom.xml/build.gradle with a Java version found'


class Sheet:
    """Collects TREFFER lines per kind with a cap, then prints FAKT counts and the hits."""

    def __init__(self, cap):
        self.cap = cap
        self.hits = {}

    def hit(self, kind, text):
        self.hits.setdefault(kind, []).append(text)

    def count(self, kind):
        return len(self.hits.get(kind, []))

    def emit(self, kinds):
        for kind in kinds:
            rows = self.hits.get(kind, [])
            print('FAKT %s_count: %d' % (kind, len(rows)))
        print('')
        for kind in kinds:
            rows = self.hits.get(kind, [])
            for r in rows[:self.cap]:
                print('TREFFER %s: %s' % (kind, r))
            if len(rows) > self.cap:
                print('# %d more %s hits not listed' % (len(rows) - self.cap, kind))


# Fact sheet for the Java idiom/exception/logging audit. Usage: idiom_facts.py <repo-root> <source-dir>
import os
import re
import sys


SENSITIVE = re.compile(r'(?i)(password|passwd|secret|apikey|api_key|credential|bearer|privatekey|accesstoken|refreshtoken|authtoken|sessiontoken)')
REGEX_CALL = re.compile(r'\bPattern\.compile\s*\(|\.(matches|replaceAll|replaceFirst|split)\s*\((?!\s*\))')
LOOP_RE = re.compile(r'\b(for|while)\s*\(')
# Parse/validation failures whose own message adds nothing for the caller: rethrowing them as a user-facing
# IllegalArgumentException without the cause is the usual validation idiom, not lost information.
PARSE_TYPES = re.compile(r'\b(NumberFormatException|DateTimeParseException|DateTimeException|URISyntaxException|'
                         r'IllegalArgumentException|PatternSyntaxException|JsonProcessingException|JsonParseException|'
                         r'MalformedURLException|InvalidPathException|ParseException)\b')
LOG_CALL = re.compile(r'\b(?:log|logger|LOG|LOGGER)\.(trace|debug|info|warn|error)\s*\(')


def top_level_params(params):
    if not params.strip():
        return []
    out, depth, cur = [], 0, ''
    for ch in params:
        if ch in '<([':
            depth += 1
        elif ch in '>)]':
            depth -= 1
        if ch == ',' and depth == 0:
            out.append(cur.strip())
            cur = ''
        else:
            cur += ch
    out.append(cur.strip())
    return out


def main():
    base = os.path.abspath(sys.argv[1])
    src_root = os.path.join(base, sys.argv[2])
    sheet = Sheet(cap=40)
    files = 0
    long_lists = []

    print('## FAKTENBLATT')
    print('# Measured deterministically (regex over the source, comments and strings removed).')
    print('# TREFFER lines are candidates with a location, not proof; check each one in the source.')
    print('')
    if not os.path.isdir(src_root):
        print('NICHT GEMESSEN: java_files_scanned (source directory %s missing)' % sys.argv[2])
        return

    for path in java_files(src_root):
        rel = os.path.relpath(path, base)
        try:
            raw = open(path, encoding='utf-8', errors='replace').read()
        except OSError:
            continue
        files += 1
        s = strip_java(raw)

        for m in methods(s):
            ctor = m['ret'] in ('public', 'protected', 'private', 'record')
            if ctor or '@Override' in m['annos']:
                continue
            params = top_level_params(m['params'])
            # request parameters of a web handler are the API's query/path surface, not a parameter object smell
            plain = [p for p in params if not re.search(r'@(RequestParam|PathVariable|RequestBody|RequestHeader|ModelAttribute|AuthenticationPrincipal)\b', p)]
            public = 'public' in m['mods'] or 'protected' in m['mods']
            if public and not re.match(r'set[A-Z]', m['name']):
                flags = [p for p in params if re.search(r'(^|\s)(boolean|Boolean)\s+\w+$', p)
                         and '@RequestParam' not in p and '@PathVariable' not in p]
                if flags:
                    sheet.hit('boolean_parameter', '%s:%d %s(%s)' % (
                        rel, m['line'], m['name'], ', '.join(re.sub(r'\s+', ' ', f).split(' ')[-1] for f in flags)))
            if (public and len(plain) >= 6) or len(plain) >= 8:
                long_lists.append((len(plain), '%s:%d %s() with %d parameters' % (rel, m['line'], m['name'], len(plain))))

        # regex compiled per loop iteration
        seen = set()
        for lm in LOOP_RE.finditer(s):
            p_close = match_paren(s, lm.end() - 1)
            b_open = s.find('{', p_close)
            if b_open < 0 or s[p_close + 1:b_open].strip():
                continue
            b_end = match_brace(s, b_open)
            for rm in REGEX_CALL.finditer(s, b_open, b_end):
                if rm.group(1) == 'split':
                    arg_open = rm.end() - 1
                    literal = raw[arg_open + 1:match_paren(s, arg_open)].strip()
                    if re.fullmatch(r'"(\\\\.|[^.$|()\[{^?*+\\\\])"', literal):
                        continue
                ln = line_of(s, rm.start())
                if (rel, ln) in seen:
                    continue
                seen.add((rel, ln))
                sheet.hit('regex_in_loop', '%s:%d %s in loop starting at line %d' % (
                    rel, ln, rm.group(0).rstrip('( '), line_of(s, lm.start())))

        # catch blocks: log-and-rethrow, lost cause, empty without comment, lost interrupt
        for cm in re.finditer(r'\bcatch\s*\(', s):
            p_close = match_paren(s, cm.end() - 1)
            header = s[cm.end():p_close]
            var_m = re.search(r'(\w+)\s*$', header)
            var = var_m.group(1) if var_m else ''
            b_open = s.find('{', p_close)
            if b_open < 0:
                continue
            b_end = match_brace(s, b_open)
            body = s[b_open + 1:b_end]
            ln = line_of(s, cm.start())
            logs_warn = re.search(r'\b(?:log|logger|LOG|LOGGER)\.(warn|error)\s*\(', body)
            if logs_warn and re.search(r'\bthrow\s+', body):
                sheet.hit('log_and_rethrow', '%s:%d catch logs (warn/error) and rethrows' % (rel, ln))
            if var:
                v = re.escape(var)
                for tm in re.finditer(r'\bthrow\s+new\s+([\w.]+)\s*\(', body):
                    args = body[tm.end():match_paren(body, tm.end() - 1)]
                    passes_cause = re.search(r'(?<![\w.])%s\b' % v, args) is not None
                    logged = re.search(r'\b(?:log|logger|LOG|LOGGER)\.\w+\s*\([^;]*(?<![\w.])%s\s*\)\s*;' % v, body) is not None
                    init_cause = re.search(r'\.(initCause|addSuppressed)\s*\(\s*%s\b' % v, body) is not None
                    parse_only = PARSE_TYPES.search(header) and not re.search(r'\b(IOException|Exception\b(?<!\w))', header)
                    interrupted = re.search(r'\bInterruptedException\b', header)
                    if not (passes_cause or logged or init_cause or parse_only or interrupted):
                        sheet.hit('lost_cause', '%s:%d catch (%s) throws %s without the cause, without the message and without logging %s' % (
                            rel, line_of(s, b_open + 1 + tm.start()), re.sub(r'\s+', ' ', header).strip(), tm.group(1), var))
            # Empty catch: always a candidate without a comment; with a comment only when it catches broadly,
            # because the comment names the intended case while Exception/Throwable also swallows every other one
            # (round 2 missed the TerminalWebSocketHandler NPE this way).
            if not body.strip():
                commented = bool(raw[b_open + 1:b_end].strip())
                broad = re.search(r'(?<![\w.])(Exception|Throwable|RuntimeException)\b', header) is not None
                if not commented or broad:
                    sheet.hit('empty_catch', '%s:%d empty catch (%s) %s' % (
                        rel, ln, re.sub(r'\s+', ' ', header).strip(),
                        'with a comment, but catches broadly' if commented else 'without a comment'))
            if re.search(r'\bInterruptedException\b', header) and not re.search(r'\binterrupt\s*\(\s*\)', body) \
                    and not re.search(r'\bthrow\s+(%s\s*;|new\s+InterruptedException\b)' % re.escape(var or 'e'), body):
                wraps = re.search(r'\bthrow\s+new\s+([\w.]+)', body)
                sheet.hit('interrupt_lost', '%s:%d catch (InterruptedException) without interrupt()%s' % (
                    rel, ln, ' - instead throws ' + wraps.group(1) if wraps else ' and without rethrowing'))

        # log arguments that look like secrets
        for lg in LOG_CALL.finditer(s):
            args = s[lg.end():match_paren(s, lg.end() - 1)]
            names = [n for n in re.findall(r'\b([A-Za-z_]\w*)\b', args) if SENSITIVE.search(n)
                     and not re.search(r'(File|Path|Dir|Name|Header|Env|Var|Count|Length|Present|Set|Configured|Id|Key[sS]?Count)$', n)]
            if names:
                sheet.hit('sensitive_log_arg', '%s:%d log.%s with %s' % (rel, line_of(s, lg.start()), lg.group(1), ', '.join(sorted(set(names)))))

        # Lombok toString/data on classes with secret-looking fields
        if re.search(r'@(ToString|Data)\b', s):
            for fm in re.finditer(r'(?m)^\s*(?:@\w+(?:\([^)]*\))?\s+)*(?:private|protected|public)?\s*(?:final\s+)?[\w<>,\s]+?\s+(\w+)\s*(?:=[^;]*)?;', s):
                if SENSITIVE.search(fm.group(1)):
                    window = s[max(0, fm.start() - 120):fm.start() + len(fm.group(0))]
                    if '@ToString.Exclude' not in window:
                        sheet.hit('tostring_sensitive_field', '%s:%d field %s in @ToString/@Data without @ToString.Exclude' % (
                            rel, line_of(s, fm.start(1)), fm.group(1)))

        # Optional.get() without a presence check
        opt_vars = set(re.findall(r'\bOptional\s*<[^;=()]*>\s+(\w+)\s*=', s))
        for om in re.finditer(r'(\w+)\.get\s*\(\s*\)|\.(findById|findFirst|findAny|max|min|reduce)\s*\([^;]*?\)\s*\.get\s*\(\s*\)', s):
            if om.group(1) and om.group(1) not in opt_vars:
                continue
            before = s[max(0, om.start() - 300):om.start()]
            if om.group(1) and re.search(r'\b%s\.(isPresent|isEmpty)\s*\(' % re.escape(om.group(1)), before):
                continue
            sheet.hit('optional_get', '%s:%d %s' % (rel, line_of(s, om.start()), re.sub(r'\s+', ' ', om.group(0))[:80]))

    for _, text in sorted(long_lists, key=lambda t: -t[0]):
        sheet.hit('long_parameter_list', text)
    print('FAKT java_files_scanned: %d' % files)
    kinds = ['lost_cause', 'empty_catch', 'interrupt_lost', 'log_and_rethrow', 'sensitive_log_arg',
             'tostring_sensitive_field', 'optional_get', 'regex_in_loop', 'boolean_parameter', 'long_parameter_list']
    sheet.emit(kinds)
    print('')
    print('## PFLICHTFELDER')
    print('PFLICHT-FAKTEN: java_files_scanned pmd_errors_findings pmd_idioms_findings')


if __name__ == '__main__':
    main()
PYEOF
